  "mat_log_vazio": "Nenhum evento de resumo registrado ainda.",
  "mat_log_cab": "REGISTRO DOS RESUMOS — {n} evento(s), do mais novo para o mais antigo",
  "mat_marcador_rot": "parei aqui",
  "mat_marcador_em": "marcador em {p}% do texto",
  "mat_saida_tit": "Você marcou trechos e ainda não salvou.\n\nO que faço com o que você marcou?",
  "mat_saida_salvar": "Salvar e sair",
  "mat_saida_sair": "Sair sem salvar",
  "mat_saida_cancelar": "Continuar aqui",
  "mat_marca_curta": "Selecione pelo menos três caracteres do texto para marcar. Frases funcionam melhor que palavras soltas, porque palavra repetida pode acabar marcada no lugar errado.",
  "mat_marca_nao_achou": "Não encontrei esse trecho no texto guardado. Se você acabou de editar, salve antes de marcar.",
  "mat_marca_ja": "Esse trecho já está marcado.",
