  "ce_sem_ancora_erro": "The answer came without anchors and with {k} card(s), but you ticked {n}. Without anchors there is no way to tell which is which: ask the AI to keep the “@@ N” lines.",
  "ce_sem_ancora_msg": "Matched by ORDER — check the before/after.",
  "ed_dsc_ramos_tit": "Branches of the subject",
  "ed_dsc_ramos_resumo": "{f} of {n} branches studied · {p}% of what the branches are worth (weighted) · {v} with overdue review",
  "ed_dsc_ramos_ver": "Show:",
  "ed_dsc_ramos_filtro_tip": "All branches, only those still to study, or only studied ones with overdue review. Always in order of what is worth most in the exam.",
  "ed_dsc_ramos_f_todos": "all ({n})",
  "ed_dsc_ramos_f_pend": "to study ({n})",
