  "ed_dsc_ramos_vazio": "No branch in this filter.",
  "ed_dsc_ramo_vale": "{p}% of the subject",
  "ed_dsc_ramo_vale_tip": "The branch's stars and how much it is worth in the subject: subject weight × topic weight × the branch's share of the topic. The list is in decreasing order of that.",
  "ed_dsc_ramo_acerto": "{p}% correct ({n})",
  "ed_dsc_ramo_acerto_tip": "You got {p}% of {n} attempt(s) on questions that mention this branch.",
  "ed_dsc_ramo_acerto_fraco_tip": "WARNING: {p}% correct in {n} attempts, below {c}% (with at least {m} attempts). Worth reinforcing this branch; weight and priority don't change on their own.",
  "ed_dsc_ramo_estudar": "study",
  "ed_dsc_ramo_revisar": "review",
