  "qm_aplicado": "Question fixed. Its answer history was kept.",
  "qm_extras": "The AI returned {n} extra question(s). They do not enter on their own:\n{lista}",
  "qm_aplicar_todas": "apply and add the other {n}",
  "qm_aplicar_todas_ajuda": "Replaces this question with the first version and saves the other {n} as new questions. They join the NEXT round.",
  "qm_aplicado_mais": "Question fixed and {n} new one(s) added. They join the next round.",
  "qm_def_resolucao": "The ANSWER is inside the statement. The question answers itself.",
  "qm_def_conversa": "AI chatter left in the text.",
  "qm_def_cabecalho": "A quiz header ended up inside the statement.",
  "qm_def_markdown": "Raw markdown left over (**, *, ###, ---).",
  "qm_def_emoji": "There is an emoji in the statement.",
  "qm_def_longo": "The statement has {n} characters. Over 900 usually means several questions glued together.",
  "qm_def_varias": "There seems to be MORE THAN ONE numbered question inside this statement.",
  "qm_def_gab_ce": "It is a True/False question but the answer key is \"{g}\".",
  "qm_def_gab_me": "The answer key is \"{g}\", which matches no option.",
  "qm_prompt": "FIX a malformed exam question. Return the SAME question, on the SAME point, only clean.\n\nPROBLEMS FOUND:\n{defeitos}\n\nRULES\n1. The STATEMENT must not contain the answer or its justification. Everything explanatory goes to COMENTARIO.\n2. No chatter with the user.\n3. No quiz headers, numbering or separators.\n4. No markdown.\n5. No emoji.\n6. ONE question only.\n7. Keep the original TYPE ({tipo}).\n8. Keep the answer legally correct; if it was wrong, fix it and explain in COMENTARIO.\n9. A True/False statement is ONE assertion to judge.\n10. Do not invent case law, article numbers or statistics.\n\nANSWER FORMAT — exactly this:\n[QUESTAO]\nTIPO: {tipo}\nBANCA: {banca}\nENUNCIADO: (clean statement)\n{opcoes_rot}GABARITO: (C or E, or the letter)\nCOMENTARIO: (why)\n[/QUESTAO]\n\nSUBJECT: {disciplina}\nTOPIC: {topico}\n\nQUESTION TO FIX:\n{atual}",
  "qs_encerrar": "finish now ({c}/{n} · {pct}%)",
  "qs_encerrar_ajuda": "Ends the round with the current score and opens the study log. The remaining {f} stay pending.",
  "qs_encerrar_conf1": "End the round with {c} of {n} ({pct}%)?\n\n{f} question(s) stay pending.",
  "qs_encerrar_conf2": "Confirm? The round ends here and the study log opens with the {n} answered.",
  "qs_registrar_nada": "Answer at least one question first.",
  "qs_registrar_varios": "This session mixed {n} topics. A study entry belongs to one topic.",
  "qs_registrar_sem_edital": "The study log is not available right now.",
  "diag_per_0": "all",
  "diag_per_1": "today only",
  "diag_per_7": "last 7 days",
  "diag_per_30": "last 30 days",
  "diag_per_ajuda": "Shows only this period's events.",
  "qs_cartao_btn": "🃏 turn into cards",
  "qs_cartao_ajuda": "Builds the prompt to turn this question into memorisation cards, in the same format as your other cards.",
  "qs_cartao_sub": "Cards from a question · {tp} · {n} already saved in this topic",
  "qs_cartao_sem_topico": "This question is not tied to a topic.",
  "qs_cartao_sem_material": "The cards panel is not available right now.",
  "qs_cartao_prompt": "You will turn ONE exam question into memorisation cards.\n\nFORMAT — one card per line; title and explanation are optional lines stuck to the card:\n@ Law > Topic > Subtopic\nquestion :: answer :: tags\n+ Literal text — wording of the provision\n\nRULES\n1. Do NOT copy the question into the card. A card asks ONE idea.\n2. One card per idea the question tests.\n3. Prefer asking the CONCEPT, not the exam item.\n4. Use only what is in the question, answer, comment and my hint.\n5. No \"::\" inside the text.\n6. Use EXACTLY these tags in the third field: {tags}\n7. Nothing before the first card or after the last.\n8. If the BOARD below is not \"—\", put under each card a line \"+ ★ Appeared in exam ▸\" followed by the board. With no board given, do not write that line.\n\n{pc_tipo}\n\n{padrao_gerar}\n\nSUBJECT: {d}\nTOPIC: {tp}\nBOARD: {banca}\n\nSTATEMENT:\n{enunciado}\n\nOPTIONS:\n{opcoes}\n\nANSWER: {gabarito}\n\nCOMMENT:\n{comentario}\n\nMY HINT:\n{dica}",
  "qs_retomar_perg": "You have a round in progress: {f} of {n} answered, {c} right ({pct}%).\n\nContinue where you left off or start over?",
